<section id="collection" class="collection"><div class="section-heading"><div><span class="eyebrow">LA COLLECTION</span><h2>À chaque journée, ses essentiels.</h2></div><span class="muted"><?= (int)$total ?> produits</span></div>
<form class="catalog-filters" method="get" action="/#collection"><div class="search-field"><?= icon('search') ?><input type="search" name="q" value="<?= e($search) ?>" placeholder="Rechercher un produit" aria-label="Rechercher un produit"></div><select name="category" aria-label="Catégorie"><option value="0">Toutes les catégories</option><?php foreach ($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= selected($category,$c['id']) ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><select name="sort" aria-label="Trier les produits"><option value="newest" <?= selected($_GET['sort'] ?? '', 'newest') ?>>Nouveautés</option><option value="price_asc" <?= selected($_GET['sort'] ?? '', 'price_asc') ?>>Prix croissant</option><option value="price_desc" <?= selected($_GET['sort'] ?? '', 'price_desc') ?>>Prix décroissant</option><option value="name" <?= selected($_GET['sort'] ?? '', 'name') ?>>Nom</option></select><button class="button secondary" type="submit">Filtrer</button></form>
<div class="product-grid"><?php foreach ($products as $p): ?><article class="product-card"><a class="product-art art-<?= e($p['illustration']) ?>" href="/products/<?= (int)$p['id'] ?>"><img loading="lazy" src="/assets/products/<?= e($p['illustration']) ?>.svg" alt="<?= e($p['name']) ?>"><?php if ((int)$p['stock']===0): ?><span class="badge">Épuisé</span><?php elseif ((int)$p['stock']<10): ?><span class="badge">Dernières pièces</span><?php endif; ?></a><div class="product-meta"><span class="eyebrow"><?= e($p['category_name']) ?></span><div><h3><a href="/products/<?= (int)$p['id'] ?>"><?= e($p['name']) ?></a></h3><strong><?= euros((int)$p['price_cents']) ?></strong></div><a class="product-discover" href="/products/<?= (int)$p['id'] ?>">Voir le produit <?= icon('arrow') ?></a></div></article><?php endforeach; ?></div>
<?php if (!$products): ?><div class="empty-panel"><h3>Aucun produit trouvé.</h3><p>Essaie un autre mot-clé ou une autre catégorie.</p><a href="/" class="button secondary">Voir toute la collection</a></div><?php endif; ?>
<?php if ($pages>1): ?><nav class="pagination" aria-label="Pages du catalogue"><?php for ($i=1;$i<=$pages;$i++): ?><a class="<?= $i===$page?'active':'' ?>" href="/?<?= e(http_build_query(array_merge($_GET,['page'=>$i]))) ?>#collection"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?></section>
